{"implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Build mutual reachability edges, canonicalize endpoint order
    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        weight = max(core_distance[u], core_distance[v], d)
        edges.append((weight, u, v))

    # Sort: weight, then u, then v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find (DSU)
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        xr, yr = find(x), find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            parent[xr] = yr
        elif rank[xr] > rank[yr]:
            parent[yr] = xr
        else:
            parent[yr] = xr
            rank[xr] += 1
        return True

    mst = []
    total_weight = 0.0
    n_nodes = len(nodes)

    for weight, u, v in edges:
        if union(u, v):
            mst.append([u, v, weight])
            total_weight += weight
            if len(mst) == n_nodes - 1:
                break

    if len(mst) != n_nodes - 1:
        raise ValueError("Input graph is disconnected; cannot produce MST")

    return {
        "mst_edges": mst,
        "total_weight": total_weight
    }"}
